"use strict";(globalThis.webpackChunkmy_tech_blog=globalThis.webpackChunkmy_tech_blog||[]).push([[60136],{16839:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"2026-10-30-domestic-market-close","metadata":{"permalink":"/blog/market/2026-10-30-domestic-market-close","source":"@site/market/2026-10-30-domestic-market-close/index.mdx","title":"2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":2.51,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-30-domestic-market-close","title":"2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\ub9c8\uac10"]},"unlisted":false,"nextItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \uc624\uc804 \ud750\ub984","permalink":"/blog/market/2026-10-30-domestic-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc774 \ubaa8\ub450 \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 3.48% \ud558\ub77d\ud55c 5,730.74\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \ub300\ube44 3.83% \ud558\ub77d\ud55c 724.38\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \uc2dc\uac00\ubd80\ud130 \uc885\uac00\uae4c\uc9c0 \uc804\uc77c \uc885\uac00\ub97c \ud68c\ubcf5\ud558\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 5,599.42\uae4c\uc9c0 \ub0b4\ub824\uac14\ub2e4\uac00 5,730.74\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc7a5\uc911 717.27\uae4c\uc9c0 \ub0b4\ub824\uac14\ub2e4\uac00 724.38\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,730.74 | -206.92 | -3.48% | 5,760.35 | 5,784.98 | 5,599.42 | 213,759\ucc9c\uc8fc | 19\uc870 2,687\uc5b5\uc6d0 |\\n| \ucf54\uc2a4\ub2e5 | 724.38 | -28.85 | -3.83% | 737.76 | 739.79 | 717.27 | 434,190\ucc9c\uc8fc | 5\uc870 7,416\uc5b5\uc6d0 |\\n\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,937.66, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 753.23\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-26 | 5,499.05 | 5,565.67 | 5,455.11 | 5,469.47 | 202,295 |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,730.74 | 213,759 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-26 | 742.17 | 745.95 | 727.20 | 727.21 | 476,231 |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 724.38 | 434,190 |\\n\\n\ucf54\uc2a4\ud53c\ub294 10\uc6d4 28\uc77c 6,000\uc120\uc744 \ub118\uae34 \ub4a4 \uc774\ud2c0 \uc5f0\uc18d \ud558\ub77d\ud574 5,700\uc120 \ucd08\ubc18\uc73c\ub85c \ub0b4\ub824\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \ucd5c\uadfc 5\uac70\ub798\uc77c \uc911 \uac00\uc7a5 \ub0ae\uc740 \uc885\uac00\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2f9\uc77c \uc218\uae09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +6,197 |\\n| \uc678\uad6d\uc778 | -16,167 |\\n| \uae30\uad00 | +7,432 |\\n| \uae30\ud0c0\ubc95\uc778 | +2,538 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +1,688 |\\n| \uc678\uad6d\uc778 | -267 |\\n| \uae30\uad00 | -1,377 |\\n| \uae30\ud0c0\ubc95\uc778 | -44 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uac1c\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uc774 \ud070 \ud3ed\uc73c\ub85c \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ucf54\uc2a4\ud53c \uc218\uae09\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc758 \uc21c\ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984\\n\\n\uc9c0\uc218 \ud558\ub77d \uc18d\uc5d0\uc11c\ub3c4 \uc0c1\uc2b9\ud55c \ud14c\ub9c8\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub9c8\uac10 \ud14c\ub9c8 \uc0c1\uc2b9\ub960\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \ud14c\ub9c8 | \ub4f1\ub77d\ub960 |\\n| --- | --- |\\n| \ubc31\uc2e0\uc5ec\uad8c | +8.88% |\\n| \ube14\ub85d\uccb4\uc778 | +5.47% |\\n| \ubcf4\uc548(\uc815\ubcf4) | +3.38% |\\n| \uc8fc\ub958\ud310\ub9e4 | +2.69% |\\n| \ud574\uc6b4 | +1.69% |\\n\\n\uc0c1\uc2b9 \ud14c\ub9c8\uac00 \uc788\uc5c8\uc74c\uc5d0\ub3c4 \ub450 \uc9c0\uc218 \ubaa8\ub450 3% \ub118\uac8c \ud558\ub77d\ud55c \uc810\uc774 \uc774\ub0a0\uc758 \ud2b9\uc9d5\uc785\ub2c8\ub2e4.<br/>\\n\ud558\ub77d\uc758 \ubc30\uacbd\uc744 \ud2b9\uc815 \uc7ac\ub8cc \ud558\ub098\ub85c \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub824\uc6b0\uba70, \uc774\ub294 \ucc38\uace0\uc6a9 \ud750\ub984 \uc815\ub9ac\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub0b4\uc77c \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 5,700\uc120\uc5d0\uc11c \uc9c0\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 720\uc120 \ubd80\uadfc\uc5d0\uc11c \uc9c0\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uc758 \ucf54\uc2a4\ud53c \uc21c\ub9e4\ub3c4 \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc0c1\uc2b9 \ud14c\ub9c8\uc758 \uc0c1\ub300\uc801 \uac15\uc138\uac00 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-10-30-domestic-market-midday","metadata":{"permalink":"/blog/market/2026-10-30-domestic-market-midday","source":"@site/market/2026-10-30-domestic-market-midday/index.mdx","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \uc624\uc804 \ud750\ub984","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/market/tags/\uc7a5\uc911"}],"readingTime":3.48,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-30-domestic-market-midday","title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \uc624\uc804 \ud750\ub984","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/market/2026-10-30-domestic-market-close"},"nextItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \ucd9c\ubc1c","permalink":"/blog/market/2026-10-30-domestic-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc624\uc804\uc7a5 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uc7a5 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc740 \ubaa8\ub450 \ud070 \ud3ed\uc758 \ud558\ub77d\uc138\ub97c \ubcf4\uc774\uba70 \uc624\uc804\uc7a5\uc744 \ub9c8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 5,600\uc120 \uc544\ub798\uae4c\uc9c0 \ubc00\ub838\ub2e4\uac00 \ub099\ud3ed\uc744 \uc77c\ubd80 \uc904\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\ub3c4 \uc7a5\uc911 \uc800\uc810 \uc774\ud6c4 \ub099\ud3ed\uc744 \ub2e4\uc18c \ucd95\uc18c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ub274\uc695 \uc99d\uc2dc\uc5d0\uc11c \uc778\uacf5\uc9c0\ub2a5 \uad00\ub828 \uae30\uc220\uc8fc\uac00 \uc57d\uc138\ub97c \ubcf4\uc778 \uc5ec\ud30c\uac00 \uad6d\ub0b4 \uc99d\uc2dc\uc5d0\ub3c4 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uad00\ub828 \ubcf4\ub3c4\uc5d0\uc11c\ub294 \uc54c\ud30c\ubcb3\uc758 \ubd80\uc9c4\ud55c \uc2e4\uc801 \uc774\ud6c4 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ube44\uc6a9\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \ud655\uc0b0\ud588\ub2e4\uace0 \uc804\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \ub9c8\uac10 \uc774\ud6c4 \uc2e4\uc801\uc744 \ubc1c\ud45c\ud55c \uc544\ub9c8\uc874\uacfc \uc778\ud154\uc774 \uc2dc\uac04 \uc678 \uac70\ub798\uc5d0\uc11c \ud558\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\ub3c4 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uc99d\uc2dc\uc5d0\uc11c\ub294 \uc7a5 \ucd08\ubc18 \ud504\ub85c\uadf8\ub7a8 \ub9e4\ub3c4\ud638\uac00 \uc77c\uc2dc\ud6a8\ub825\uc815\uc9c0, \uc774\ub978\ubc14 \ub9e4\ub3c4 \uc0ac\uc774\ub4dc\uce74\uac00 \ubc1c\ub3d9\ub410\ub2e4\ub294 \ubcf4\ub3c4\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub7ec\ud55c \ud750\ub984\uc740 \uc624\uc804\uc7a5 \ud558\ub77d\uc758 \ubc30\uacbd\uc73c\ub85c \uc5b8\uae09\ub418\uace0 \uc788\uc73c\uba70, \uac1c\ubcc4 \uc885\ubaa9\uc758 \ud750\ub984\uc744 \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,662.39 | -275.27 | -4.64% | 5,760.35 | 5,784.98 | 5,599.42 | 120,598\ucc9c\uc8fc | 9\uc870 9,954\uc5b5\uc6d0 | 2026-10-30 12:29 KST |\\n| \ucf54\uc2a4\ub2e5 | 723.09 | -30.14 | -4.00% | 737.76 | 739.79 | 717.27 | 296,616\ucc9c\uc8fc | 3\uc870 5,088\uc5b5\uc6d0 | 2026-10-30 12:29 KST |\\n\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70, \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 \uc774\ud6c4\uc5d0\ub3c4 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,937.66, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 753.23\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-23 | 5,403.17 | 5,550.30 | 5,305.98 | 5,550.30 | 249,517 |\\n| 2026-10-26 | 5,499.05 | 5,565.67 | 5,455.11 | 5,469.47 | 202,295 |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,599.42 | 5,657.20 | 119,727 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-23 | 748.32 | 753.02 | 732.87 | 751.69 | 505,474 |\\n| 2026-10-26 | 742.17 | 745.95 | 727.20 | 727.21 | 476,231 |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.79 | 717.27 | 721.85 | 295,045 |\\n\\n2026\ub144 10\uc6d4 30\uc77c \ubd09\uc740 \uc7a5\uc911 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc77c\ubd09 \ud45c\uc758 \ub2f9\uc77c \uc885\uac00\ub294 \ud45c \uc791\uc131 \uc2dc\uc810\uc758 \ud615\uc131 \uc911 \uc218\uce58\uc774\uba70 \uc2e4\uc2dc\uac04 \ud604\uc7ac\uac00\uc640 \uc2dc\ucc28\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c 6,000\uc120\uc744 \ub118\uacbc\ub358 \ud750\ub984\uc5d0\uc11c \ud558\ub8e8 \ub9cc\uc5d0 \ud070 \ud3ed\uc73c\ub85c \ub418\ub3cc\ub9bc\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c 753.23\uc5d0\uc11c \ud558\ub77d\ud574 720\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984 \ubcc0\ud654\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,760.35\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc7a5\uc911 \uc800\uc810 5,599.42\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc800\uc810 \ub300\ube44\ub85c\ub294 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,662.39\uae4c\uc9c0 \ub099\ud3ed\uc744 \uc77c\ubd80 \uc904\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 737.76\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc7a5\uc911 \uc800\uc810 717.27\uae4c\uc9c0 \ubc00\ub838\uc2b5\ub2c8\ub2e4.<br/>\\n\uc800\uc810 \ub300\ube44\ub85c\ub294 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 723.09\uae4c\uc9c0 \ub099\ud3ed\uc744 \ub2e4\uc18c \ucd95\uc18c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \uc9c0\uc218 \ubaa8\ub450 \uc2dc\uac00 \ub300\ube44 \ud558\ub77d \ubc29\ud5a5\uc774 \uc720\uc9c0\ub41c \uac00\uc6b4\ub370, \uc800\uc810\uc5d0\uc11c\uc758 \ubc18\ub4f1 \uc2dc\ub3c4\uac00 \ub098\ud0c0\ub0ac\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \ub300\uc2dc\ubcf4\ub4dc \uc870\ud68c \uc2dc\uc810\uc758 \ud14c\ub9c8 \ud56d\ubaa9\uc740 \ube44\uc5b4 \uc788\uc5b4, \uc624\uc804 \uac15\ud588\ub358 \ud14c\ub9c8\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc0c1\uc2b9\ub960 \uc0c1\uc704\uc5d0\ub294 \uac1c\ubcc4 \uc885\ubaa9 \uc911\uc2ec\uc758 \uc6c0\uc9c1\uc784\uc774 \uc788\uc5c8\uc73c\ub098, \uc9c0\uc218 \uc804\uccb4\uc758 \ud558\ub77d \ud750\ub984\uacfc\ub294 \ubcc4\uac1c\ub85c \ud574\uc11d\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc804\uc77c \uc218\uae09\\n\\n\uc804\uc77c\uc778 2026\ub144 10\uc6d4 29\uc77c \uc218\uae09\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc218\uae09 \ud655\uc815\uce58\ub294 \uc544\uc9c1 \uc9d1\uacc4 \uc911\uc774\ubbc0\ub85c \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | -429 |\\n| \uc678\uad6d\uc778 | +1,221 |\\n| \uae30\uad00 | -4,132 |\\n| \uae30\ud0c0\ubc95\uc778 | +3,340 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +2,058 |\\n| \uc678\uad6d\uc778 | -1,210 |\\n| \uae30\uad00 | -740 |\\n| \uae30\ud0c0\ubc95\uc778 | -108 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uac1c\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uae30\uad00 \uc21c\ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc774\ub0a0 \uc218\uae09\uc5d0\uc11c \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ud6c4\uc5d0 \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 5,600\uc120 \ubd80\uadfc\uc5d0\uc11c \ub099\ud3ed\uc744 \ucd94\uac00\ub85c \uc904\uc774\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 720\uc120 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uc800\uc810 \uc774\ud6c4\uc758 \ubc18\ub4f1 \uc2dc\ub3c4\uac00 \uc624\ud6c4\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uae30\uc220\uc8fc \uc6b0\ub824\uc640 \uad00\ub828\ub41c \ud750\ub984\uc774 \uc624\ud6c4\uc5d0 \uc644\ud654\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc218\uae09 \ud655\uc815\uce58\uac00 \uc9d1\uacc4\ub418\ub294 \ub300\ub85c \uc678\uad6d\uc778\xb7\uae30\uad00\uc758 \ubc29\ud5a5\uc744 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc624\uc804\uc7a5 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ud070 \ud3ed\uc73c\ub85c \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-10-30-domestic-market-open","metadata":{"permalink":"/blog/market/2026-10-30-domestic-market-open","source":"@site/market/2026-10-30-domestic-market-open/index.mdx","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \ucd9c\ubc1c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/market/tags/\uc7a5\uc624\ud508"}],"readingTime":2.88,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-30-domestic-market-open","title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \ucd9c\ubc1c","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5\uc911 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \uc624\uc804 \ud750\ub984","permalink":"/blog/market/2026-10-30-domestic-market-midday"},"nextItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/market/2026-10-30-nasdaq-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 30\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ubc30\uacbd\\n\\n\uac04\ubc24 \ubbf8\uad6d \uc99d\uc2dc\ub294 \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 26,184.72\ub85c \uc804\uc77c \ub300\ube44 365.13\ud3ec\uc778\ud2b8, 1.38% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2a4\ud0e0\ub354\ub4dc\uc564\ub4dc\ud478\uc5b4\uc2a4 500 \uc9c0\uc218\ub294 7,720.39\ub85c \uc804\uc77c \ub300\ube44 23.59\ud3ec\uc778\ud2b8, 0.30% \ud558\ub77d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad00\ub828 \ubcf4\ub3c4\uc5d0\uc11c\ub294 \uc54c\ud30c\ubcb3\uc758 \ubd80\uc9c4\ud55c \uc2e4\uc801\uc774 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ube44\uc6a9 \uc6b0\ub824\ub97c \uc790\uadf9\ud558\uba70 \ub274\uc695 \uc99d\uc2dc \uae30\uc220\uc8fc \ud22c\uc790 \uc2ec\ub9ac\ub97c \uc704\ucd95\uc2dc\ucf30\ub2e4\uace0 \uc804\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub7ec\ud55c \ud750\ub984\uc774 \uad6d\ub0b4 \uc99d\uc2dc \uac1c\uc7a5 \ucd08\ubc18 \uc57d\uc138 \ucd9c\ubc1c\uc758 \ubc30\uacbd\uc73c\ub85c \uc5b8\uae09\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uac1c\ubcc4 \uc885\ubaa9\uc758 \ud750\ub984\uc744 \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub824\uc6b0\uba70, \uc774\ub294 \ucc38\uace0\uc6a9 \ubc30\uacbd \uc815\ub9ac\uc785\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 | \uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,719.05 | -218.61 | -3.68% | 5,760.35 | 5,784.98 | 5,679.80 | 37,046\ucc9c\uc8fc | 3\uc870 4,429\uc5b5\uc6d0 | 2026-10-30 09:29 KST |\\n| \ucf54\uc2a4\ub2e5 | 737.55 | -15.68 | -2.08% | 737.76 | 739.32 | 726.68 | 113,072\ucc9c\uc8fc | 1\uc870 2,259\uc5b5\uc6d0 | 2026-10-30 09:29 KST |\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc740 \ubaa8\ub450 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc2dc\uac00 5,760.35\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 5,719.05\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc2dc\uac00 737.76\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc2a4\ub0c5\uc0f7 \uc2dc\uc810 737.55\ub97c \uae30\ub85d\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 5,937.66, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 753.23\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-23 | 5,403.17 | 5,550.30 | 5,305.98 | 5,550.30 | 249,517 |\\n| 2026-10-26 | 5,499.05 | 5,565.67 | 5,455.11 | 5,469.47 | 202,295 |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 296,495 |\\n| 2026-10-30 | 5,760.35 | 5,784.98 | 5,679.80 | 5,728.65 | 36,366 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-23 | 748.32 | 753.02 | 732.87 | 751.69 | 505,474 |\\n| 2026-10-26 | 742.17 | 745.95 | 727.20 | 727.21 | 476,231 |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 494,052 |\\n| 2026-10-30 | 737.76 | 739.32 | 726.68 | 739.05 | 111,266 |\\n\\n2026\ub144 10\uc6d4 30\uc77c \ubd09\uc740 \uc7a5\uc911 \ud615\uc131 \uc911\uc778 \ubd09\uc774\uba70 \uc885\uac00\ub294 \ud655\uc815\uac12\uc774 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\uc77c\ubd09 \ud45c\uc758 \ub2f9\uc77c \uc885\uac00\ub294 \ud45c \uc791\uc131 \uc2dc\uc810\uc758 \ud615\uc131 \uc911 \uc218\uce58\uc774\uba70 \uc2e4\uc2dc\uac04 \ud604\uc7ac\uac00\uc640 \uc2dc\ucc28\uac00 \uc788\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c 5,937.66\uc5d0\uc11c \ud558\ub77d \ucd9c\ubc1c\ud574 5,700\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c 753.23\uc5d0\uc11c \ud558\ub77d \ucd9c\ubc1c\ud574 740\uc120 \ubd80\uadfc\uc5d0\uc11c \uc6c0\uc9c1\uc774\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc804\uc77c \uc218\uae09\\n\\n\uc804\uc77c\uc778 2026\ub144 10\uc6d4 29\uc77c \uc218\uae09\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | -429 |\\n| \uc678\uad6d\uc778 | +1,221 |\\n| \uae30\uad00 | -4,132 |\\n| \uae30\ud0c0\ubc95\uc778 | +3,340 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +2,058 |\\n| \uc678\uad6d\uc778 | -1,210 |\\n| \uae30\uad00 | -740 |\\n| \uae30\ud0c0\ubc95\uc778 | -108 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uac1c\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uae30\uad00 \uc21c\ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc774\ub0a0 \uc218\uae09\uc5d0\uc11c \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 5,700\uc120 \ubd80\uadfc\uc5d0\uc11c \ub099\ud3ed\uc744 \uc904\uc774\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 740\uc120 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc678\uad6d\uc778\uacfc \uae30\uad00\uc758 \uc7a5 \ucd08\ubc18 \uc218\uae09 \ubc29\ud5a5\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uac04\ubc24 \ubbf8\uad6d \uae30\uc220\uc8fc \uc6b0\ub824\uc640 \uad00\ub828\ub41c \ud750\ub984\uc774 \uc7a5\uc911 \uc644\ud654\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uc7a5 \ucd08\ubc18 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"2026-10-30-nasdaq-market-close","metadata":{"permalink":"/blog/market/2026-10-30-nasdaq-market-close","source":"@site/market/2026-10-30-nasdaq-market-close/index.mdx","title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":2.22,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-30-nasdaq-market-close","title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 \uc7a5 \uc624\ud508 \ubd84\uc11d, \ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc758 \ucd9c\ubc1c","permalink":"/blog/market/2026-10-30-domestic-market-open"},"nextItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","permalink":"/blog/market/2026-10-30-nasdaq-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc804\uc77c \ub300\ube44 \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d\ub960\uc740 2.86%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\ub3c4 \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc73c\ub098 \ub099\ud3ed\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ubcf4\ub3c4\uc5d0\uc11c\ub294 \uc54c\ud30c\ubcb3\uacfc \uc544\ub9c8\uc874 \ub4f1 \ub300\ud615 \uae30\uc220\uc8fc\uc758 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4 \uc6b0\ub824\uac00 \uac70\ub860\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \ub2f9\uc77c \uace0\uac00 | \ub2f9\uc77c \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,437.00 | -747.72 | -2.86% | 26,184.72 | 25,657.97 | 25,191.32 |\\n| S&P500 | 7,580.07 | -140.32 | -1.82% | 7,720.39 | 7,635.77 | 7,529.84 |\\n| \ub2e4\uc6b0\uc9c0\uc218 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 10\uc6d4 30\uc77c 16\uc2dc 20\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 10\uc6d4 31\uc77c 05\uc2dc 20\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7 \uc218\uce58\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \uc885\uac00\uc5d0\uc11c \uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc744 \ube7c\ub294 \ubc29\uc2dd\uc73c\ub85c \uc5ed\uc0b0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub294 \uc804\uc77c \ub9c8\uac10 \uae00\uc758 \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uace0\uac00\uc640 \uc800\uac00\ub294 \ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4\uc758 \ucd5c\ub300\uac12\uacfc \ucd5c\uc18c\uac12\uc73c\ub85c \uc0b0\ucd9c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\ub294 \uc9c1\uc811 \uc870\ud68c\uc5d0\uc11c \uc218\uce58 \ucd94\ucd9c\uc774 \ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \ubcf8\ubb38 \uc2a4\ub0c5\uc0f7\uc740 \ub124\uc774\ubc84 \uac12\uc774 \uc544\ub2c8\ub77c \ud55c\ud22c MTS \uad50\ucc28\uac12\uc73c\ub85c \ucc44\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc640 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub9c8\uac10 \uc6d0\uc778\uc740 \ubcf8\ubb38\uc5d0 \uc4f0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ub9c8\uac10 \ud750\ub984\\n\\nS&P500\uc740 7,580.07\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 -140.32, \ub4f1\ub77d\ub960\uc740 -1.82%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,720.39\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \ub2f9\uc77c \uace0\uac00\ub294 7,635.77, \ub2f9\uc77c \uc800\uac00\ub294 7,529.84\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \ub9c8\uac10 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \ub098\uc2a4\ub2e5 \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc74c \uac70\ub798\uc77c \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5\uc774 \ub2f9\uc77c \uc800\uac00 25,191.32 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uacfc S&P500\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\ub3c4 \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \uc885\uac00 26,184.72 \ubd80\uadfc\uc73c\ub85c \ub418\ub3cc\ub9ac\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \ub2e4\uc6b0\uc9c0\uc218 \ub9c8\uac10 \uc218\uce58\uac00 \ud655\uc778\ub418\ub294 \ub300\ub85c \uc138 \uc9c0\uc218\uc758 \ubc29\ud5a5\uc774 \uc77c\uce58\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub9c8\uac10 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ub2e4\uc74c \uac70\ub798\uc77c\uc758 \uacb0\uacfc\ub97c \ubcf4\uc7a5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5\uc740 2.86% \ud558\ub77d\uc73c\ub85c \ud55c \uc8fc\ub97c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\ub294 \uc800\uac00 \uc9c0\uc9c0 \uc5ec\ubd80\uc640 \uc9c0\uc218 \uac04 \ub099\ud3ed \ucc28\uc774\ub97c \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac83\uc774 \ub3c4\uc6c0\uc774 \ub429\ub2c8\ub2e4.<br/>"},{"id":"2026-10-30-nasdaq-market-midday","metadata":{"permalink":"/blog/market/2026-10-30-nasdaq-market-midday","source":"@site/market/2026-10-30-nasdaq-market-midday/index.mdx","title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/market/tags/\uc7a5\uc911"}],"readingTime":2.51,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-30-nasdaq-market-midday","title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/market/2026-10-30-nasdaq-market-close"},"nextItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","permalink":"/blog/market/2026-10-30-nasdaq-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5\uc911 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc7a5\uc911\uc5d0\ub3c4 \ud558\ub77d \ud750\ub984\uc744 \uc774\uc5b4\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uc2a4\ub0c5\uc0f7\ubcf4\ub2e4 \ub099\ud3ed\uc774 \ucee4\uc84c\uc73c\uba70 \uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658\uc740 \ub098\ud0c0\ub098\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d \uc555\ub825\uc740 \ub098\uc2a4\ub2e5\uc774 S&P500\ubcf4\ub2e4 \ud06c\uac8c \ubc1b\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc30\uacbd\uc73c\ub85c\ub294 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uc7a5\uc911\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,412.36 | -772.36 | -2.95% | 26,184.72 | 25,673.00 | 25,397.52 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 10\uc6d4 30\uc77c 12\uc2dc 56\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 10\uc6d4 31\uc77c 01\uc2dc 56\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc218\uce58\ub294 \uc7a5\uc774 \uc9c4\ud589 \uc911\uc774\ub77c \uacc4\uc18d \ubcc0\ud558\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc218\uce58\ub294 \ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud55c \uac12\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc640 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub3c4 26,184.72\ub85c \ub124\uc774\ubc84 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc7a5\uc911 \uc2dc\uac00\ub294 25,592.49\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n\ucc28\ud2b8\uc758 \uc9c1\uc804 \uac70\ub798\uc77c\uc778 2026\ub144 10\uc6d4 29\uc77c \uc885\uac00\ub294 26,184.72\ub85c \ub124\uc774\ubc84 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ud615\uc131 \uc911\uc778 \ub2f9\uc77c \ubd09\uc758 \uc2dc\uac00\uc640 \uc7a5\uc911 \uace0\uac00, \uc7a5\uc911 \uc800\uac00\ub3c4 \ub124\uc774\ubc84 \uc7a5\uc911 \uac12\uacfc \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ud750\ub984\\n\\nS&P500\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub099\ud3ed\uc774 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900 S&P500\uc740 7,580.70, \uc804\uc77c \ub300\ube44 -139.69, \ub4f1\ub77d\ub960 -1.81%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,720.39\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \uc7a5\uc911 \uace0\uac00\ub294 7,635.77, \uc7a5\uc911 \uc800\uac00\ub294 7,579.27\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \uae30\uc220\uc8fc \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uacfc \uc624\ud6c4 \ud750\ub984 \ubcc0\ud654\\n\\n\uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658\uc740 \ub098\ud0c0\ub098\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \ud604\uc7ac\uac00\ub294 \uc2dc\uac00 25,592.49\ubcf4\ub2e4 180.13 \ub0ae\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \uc2a4\ub0c5\uc0f7\uc778 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 10\uc2dc 02\ubd84 \uae30\uc900 25,643.49\ubcf4\ub2e4\ub3c4 231.13 \ub0ae\uc544\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ub4f1\ub77d\ub960\ub3c4 \uc624\uc804 -2.07%\uc5d0\uc11c \uc7a5\uc911 -2.95%\ub85c \ub099\ud3ed\uc774 \ud655\ub300\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uac00\ub294 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc558\uc73c\ub098 \ud604\uc7ac\uac00\ub294 \uace0\uac00 \ubd80\uadfc\uc744 \uc9c0\ud0a4\uc9c0 \ubabb\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804 \ud558\ub77d\uc774 \uc624\ud6c4 \ub4e4\uc5b4 \ub418\ub3cc\ub824\uc9c0\uc9c0 \uc54a\uace0 \uc774\uc5b4\uc9c4 \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10\uae4c\uc9c0 \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uc800\uac00 25,397.52 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uc804\uc77c \ub300\ube44 \ub099\ud3ed\uc774 \ub9c8\uac10\uae4c\uc9c0 \ucd95\uc18c\ub418\ub294\uc9c0 \ud655\ub300\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, S&P500\uacfc \ub098\uc2a4\ub2e5\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \ub9c8\uac10\uae4c\uc9c0 \uc881\ud600\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4\uc5d0 \ub300\ud55c \ud3c9\uac00\uac00 \uc7a5 \ud6c4\ubc18\uc5d0\ub3c4 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ud655\uc815\ub41c \uacb0\uacfc\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4\uc5d0 \ub300\ud55c \uc6b0\ub824 \uc18d\uc5d0 \uc7a5\uc911\uc5d0\ub3c4 \ud558\ub77d \ud750\ub984\uc744 \uc774\uc5b4\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58\ub85c \ud655\uc778\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-10-30-nasdaq-market-open","metadata":{"permalink":"/blog/market/2026-10-30-nasdaq-market-open","source":"@site/market/2026-10-30-nasdaq-market-open/index.mdx","title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-30T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/market/tags/\uc7a5\uc624\ud508"}],"readingTime":2.35,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-30-nasdaq-market-open","title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","permalink":"/blog/market/2026-10-30-nasdaq-market-midday"},"nextItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/market/2026-10-29-nasdaq-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uac1c\uc7a5 \ubc30\uacbd\\n\\n\ub098\uc2a4\ub2e5\uc740 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804 \uc7ac\ub8cc\ub85c\ub294 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4\uc5d0 \ub300\ud55c \uc6b0\ub824\uac00 \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc54c\ud30c\ubcb3\uc740 3\ubd84\uae30 \uc790\ubcf8\uc9c0\ucd9c\uc774 \uc804\ub144 \ub300\ube44 114% \uae09\uc99d\ud588\ub2e4\ub294 \ubcf4\ub3c4\uc640 \ud568\uaed8 \uc2e4\uc801 \uc1fc\ud06c\ub85c \uc8fc\uac00\uac00 13% \uae09\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc544\ub9c8\uc874\uc740 2,200\uc5b5 \ub2ec\ub7ec \uaddc\ubaa8 \uc778\uacf5\uc9c0\ub2a5 \uc778\ud504\ub77c \ud22c\uc790 \uacc4\ud68d\uc744 \uc720\uc9c0\ud558\uba74\uc11c \ud604\uae08\ud750\ub984 \uc545\ud654 \uc6b0\ub824\uac00 \uc81c\uae30\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\ud154\uc740 \uc2e4\uc801\uc804\ub9dd \uc545\ud654\uac00 \ud568\uaed8 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ud68c\uc758\ub860\uc774 \ub2e4\uc2dc \ubd80\uac01\ub418\uba74\uc11c \uae30\uc220\uc8fc \uc911\uc2ec\uc758 \ub098\uc2a4\ub2e5 \ucd08\ubc18 \ud750\ub984\uc744 \uc555\ubc15\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 25,643.49 | -541.23 | -2.07% | 26,184.72 | 25,657.97 | 25,537.64 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 10\uc6d4 30\uc77c 10\uc2dc 02\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 10\uc6d4 30\uc77c 23\uc2dc 02\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc218\uce58\ub294 \uc7a5\uc774 \uc9c4\ud589 \uc911\uc774\ub77c \uacc4\uc18d \ubcc0\ud558\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\ub294 \uc9c1\uc811 \uc870\ud68c\uc5d0\uc11c \uac00\uaca9 \ub370\uc774\ud130\ub97c \ub2f4\uc740 \ubcf8\ubb38\uc774 \ubc18\ud658\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\uc5d0 \ub530\ub77c \uc2a4\ub0c5\uc0f7 \uc218\uce58\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uac12\uc73c\ub85c \ucc44\uc6e0\uc73c\uba70 \ub124\uc774\ubc84 \uac12\uc778 \uac83\ucc98\ub7fc \ud45c\uae30\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc640 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub294 26,184.72\ub85c \uc77c\ubd09 \uae30\uc900 2026\ub144 10\uc6d4 29\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 \uc7a5\uc911 \uace0\uac00\ub294 25,657.97, \uc7a5\uc911 \uc800\uac00\ub294 25,537.64\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ud750\ub984\\n\\nS&P500\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub099\ud3ed\uc774 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900 S&P500\uc740 7,628.20, \uc804\uc77c \ub300\ube44 -92.19, \ub4f1\ub77d\ub960 -1.19%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,720.39\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \uc7a5\uc911 \uace0\uac00\ub294 7,635.77, \uc7a5\uc911 \uc800\uac00\ub294 7,622.27\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \uc7a5 \uc624\ud508 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \uae30\uc220\uc8fc \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \uc54c\ud30c\ubcb3\uacfc \uc544\ub9c8\uc874, \uc778\ud154 \uad00\ub828 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4 \ud3c9\uac00\uac00 \uc7a5\uc911\uc5d0 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uc800\uac00 25,537.64 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, S&P500\uacfc \ub098\uc2a4\ub2e5\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \uc7a5\uc911\uc5d0 \uc881\ud600\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \uc7a5 \ub9c8\uac10 \ub54c\uae4c\uc9c0 \uace0\uac00\uc640 \uc800\uac00\uc758 \ubc94\uc704\uac00 \uc5b4\ub5bb\uac8c \ubcc0\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ud655\uc815\ub41c \uacb0\uacfc\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \ubd80\ub2f4\uc5d0 \ub300\ud55c \uc6b0\ub824 \uc18d\uc5d0 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58\ub85c \ud655\uc778\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-10-29-nasdaq-market-close","metadata":{"permalink":"/blog/market/2026-10-29-nasdaq-market-close","source":"@site/market/2026-10-29-nasdaq-market-close/index.mdx","title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":2.14,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-29-nasdaq-market-close","title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 30\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","permalink":"/blog/market/2026-10-30-nasdaq-market-open"},"nextItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/market/2026-10-29-domestic-market-close"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc804\uc77c \ub300\ube44 \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud558\ub77d\ub960\uc740 1.38%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\ub3c4 \ud558\ub77d\uc73c\ub85c \ub9c8\uac10\ud588\uc73c\ub098 \ub099\ud3ed\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \ub2f9\uc77c \uace0\uac00 | \ub2f9\uc77c \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 26,184.72 | -365.13 | -1.38% | 26,549.85 | 26,273.73 | 26,076.80 |\\n| S&P500 | 7,720.39 | -23.59 | -0.30% | 7,743.98 | 7,729.59 | 7,692.26 |\\n| \ub2e4\uc6b0\uc9c0\uc218 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 | \ud655\uc778 \ud544\uc694 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 10\uc6d4 29\uc77c 16\uc2dc 20\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 10\uc6d4 30\uc77c 05\uc2dc 20\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\uc2a4\ub0c5\uc0f7 \uc218\uce58\ub294 \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \ud655\uc778\ud55c \ub9c8\uac10 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \uc885\uac00\ub294 \uc885\uac00\uc5d0\uc11c \uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc744 \ube7c\ub294 \ubc29\uc2dd\uc73c\ub85c \uc5ed\uc0b0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uace0\uac00\uc640 \uc800\uac00\ub294 \ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4\uc758 \ucd5c\ub300\uac12\uacfc \ucd5c\uc18c\uac12\uc73c\ub85c \uc0b0\ucd9c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ud398\uc774\uc9c0\ub294 \uc9c1\uc811 \uc870\ud68c\uc5d0\uc11c \uc218\uce58 \ucd94\ucd9c\uc774 \ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub530\ub77c\uc11c \ubcf8\ubb38 \uc2a4\ub0c5\uc0f7\uc740 \ub124\uc774\ubc84 \uac12\uc774 \uc544\ub2c8\ub77c \ud55c\ud22c MTS \uad50\ucc28\uac12\uc73c\ub85c \ucc44\uc6e0\uc2b5\ub2c8\ub2e4.<br/>\\n\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8 \ucd9c\ucc98\ub294 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc640 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub525\uc11c\uce58 \uad50\ucc28\uac80\uc99d\uc740 \uc11c\ubc84 \uc624\ub958\ub85c \uc2e4\ud328\ud574 \ub9c8\uac10 \uc774\uc288 \ubcf4\uac15\uc740 \uc0dd\ub7b5\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud655\uc778\ub418\uc9c0 \uc54a\uc740 \ub9c8\uac10 \uc6d0\uc778\uc740 \ubcf8\ubb38\uc5d0 \uc4f0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ub9c8\uac10 \ud750\ub984\\n\\nS&P500\uc740 7,720.39\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc804\uc77c \ub300\ube44 \ubcc0\ub3d9\ud3ed\uc740 -23.59, \ub4f1\ub77d\ub960\uc740 -0.30%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,743.98\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \ub2f9\uc77c \uace0\uac00\ub294 7,729.59, \ub2f9\uc77c \uc800\uac00\ub294 7,692.26\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \ub9c8\uac10 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \ub098\uc2a4\ub2e5 \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2e4\uc74c \uac70\ub798\uc77c \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \ub098\uc2a4\ub2e5\uc774 \ub2f9\uc77c \uc800\uac00 26,076.80 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uacfc S&P500\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \ub2e4\uc74c \uac70\ub798\uc77c\uc5d0\ub3c4 \uc720\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc804\uc77c \uc885\uac00 26,549.85 \ubd80\uadfc\uc73c\ub85c \ub418\ub3cc\ub9ac\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, \ub2e4\uc6b0\uc9c0\uc218 \ub9c8\uac10 \uc218\uce58\uac00 \ud655\uc778\ub418\ub294 \ub300\ub85c \uc138 \uc9c0\uc218\uc758 \ubc29\ud5a5\uc774 \uc77c\uce58\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub9c8\uac10 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ub2e4\uc74c \uac70\ub798\uc77c\uc758 \uacb0\uacfc\ub97c \ubcf4\uc7a5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 1% \ub118\ub294 \ud558\ub77d\uc73c\ub85c 10\uc6d4 29\uc77c \uac70\ub798\ub97c \ub9c8\ucce4\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58\ub85c \ud655\uc778\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-10-29-domestic-market-close","metadata":{"permalink":"/blog/market/2026-10-29-domestic-market-close","source":"@site/market/2026-10-29-domestic-market-close/index.mdx","title":"2026\ub144 10\uc6d4 29\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uad6d\ub0b4","permalink":"/blog/market/tags/\uad6d\ub0b4"},{"inline":true,"label":"\uc7a5\ub9c8\uac10","permalink":"/blog/market/tags/\uc7a5\ub9c8\uac10"}],"readingTime":2.58,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-29-domestic-market-close","title":"2026\ub144 10\uc6d4 29\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\uad6d\ub0b4","\uc7a5\ub9c8\uac10"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/market/2026-10-29-nasdaq-market-close"},"nextItem":{"title":"\uc2dc\ud669 \uc139\uc158 \uc2dc\uc791 \uc548\ub0b4","permalink":"/blog/market/market-section-opening"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 29\uc77c \uad6d\ub0b4 \uc99d\uc2dc \uc7a5 \ub9c8\uac10 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10 \uc694\uc57d\\n\\n\ucf54\uc2a4\ud53c\uc640 \ucf54\uc2a4\ub2e5\uc774 \ubaa8\ub450 \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c \ub300\ube44 1.24% \ud558\ub77d\ud55c 5,937.66\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc804\uc77c \ub300\ube44 2.34% \ud558\ub77d\ud55c 753.23\uc5d0 \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uace0\uc810 \ub300\ube44\ub85c\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \uc544\ub798\uc5d0\uc11c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c\ub294 \uc7a5\uc911 6,100.11\uae4c\uc9c0 \uc62c\ub790\uc73c\ub098 \uc885\uac00\ub294 5,937.66\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 \uc7a5\uc911 768.75\uae4c\uc9c0 \uc62c\ub790\uc73c\ub098 \uc885\uac00\ub294 753.23\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \ub9c8\uac10 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \uc885\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uac70\ub798\ub7c9 | \uac70\ub798\ub300\uae08 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ucf54\uc2a4\ud53c | 5,937.66 | -74.78 | -1.24% | 6,017.22 | 6,100.11 | 5,817.92 | 279,659\ucc9c\uc8fc | 24\uc870 9,071\uc5b5\uc6d0 |\\n| \ucf54\uc2a4\ub2e5 | 753.23 | -18.05 | -2.34% | 767.78 | 768.75 | 741.96 | 468,753\ucc9c\uc8fc | 5\uc870 8,154\uc5b5\uc6d0 |\\n\\n\uc804\uc77c \uc885\uac00\ub294 \ub124\uc774\ubc84 \uc2e4\uc2dc\uac04 \uc218\uce58\uc640 \uc77c\ubd09 \uc885\uac00\ub97c \uad50\ucc28 \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ud53c \uc804\uc77c \uc885\uac00\ub294 6,012.44, \ucf54\uc2a4\ub2e5 \uc804\uc77c \uc885\uac00\ub294 771.28\uc785\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ucc28\ud2b8\ub294 [\ucf54\uc2a4\ud53c](https://finance.naver.com/sise/sise_index.naver?code=KOSPI)\uc640 [\ucf54\uc2a4\ub2e5](https://finance.naver.com/sise/sise_index.naver?code=KOSDAQ)\uc5d0\uc11c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\\n![\ucf54\uc2a4\ud53c \uc77c\ubd09 \ucc28\ud2b8](./kospi.png)\\n\\n![\ucf54\uc2a4\ub2e5 \uc77c\ubd09 \ucc28\ud2b8](./kosdaq.png)\\n\\n## \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-23 | 5,403.17 | 5,550.30 | 5,305.98 | 5,550.30 | 249,517 |\\n| 2026-10-26 | 5,499.05 | 5,565.67 | 5,455.11 | 5,469.47 | 202,295 |\\n| 2026-10-27 | 5,658.65 | 5,737.61 | 5,612.92 | 5,638.34 | 196,172 |\\n| 2026-10-28 | 5,763.85 | 6,032.28 | 5,745.51 | 6,012.44 | 237,337 |\\n| 2026-10-29 | 6,017.22 | 6,100.11 | 5,817.92 | 5,937.66 | 279,659 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \ub0a0\uc9dc | \uc2dc\uac00 | \uace0\uac00 | \uc800\uac00 | \uc885\uac00 | \uac70\ub798\ub7c9(\ucc9c\uc8fc) |\\n| --- | --- | --- | --- | --- | --- |\\n| 2026-10-23 | 748.32 | 753.02 | 732.87 | 751.69 | 505,474 |\\n| 2026-10-26 | 742.17 | 745.95 | 727.20 | 727.21 | 476,231 |\\n| 2026-10-27 | 743.09 | 760.59 | 740.17 | 743.83 | 539,957 |\\n| 2026-10-28 | 756.90 | 773.28 | 756.57 | 771.28 | 560,627 |\\n| 2026-10-29 | 767.78 | 768.75 | 741.96 | 753.23 | 468,753 |\\n\\n\ucf54\uc2a4\ud53c\ub294 \uc804\uc77c 6,000\uc120\uc744 \ub118\uae34 \ub4a4 \ud558\ub8e8 \ub9cc\uc5d0 \ub2e4\uc2dc \uc544\ub798\ub85c \ub0b4\ub824\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc740 5\uac70\ub798\uc77c \uc911 \uac00\uc7a5 \ub0ae\uc740 \uc885\uac00\ub85c \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub2f9\uc77c \uc218\uae09\\n\\n### \ucf54\uc2a4\ud53c\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +327 |\\n| \uc678\uad6d\uc778 | +763 |\\n| \uae30\uad00 | -4,472 |\\n| \uae30\ud0c0\ubc95\uc778 | +3,383 |\\n\\n### \ucf54\uc2a4\ub2e5\\n\\n| \uc8fc\uccb4 | \uc21c\ub9e4\uc218(\uc5b5\uc6d0) |\\n| --- | --- |\\n| \uac1c\uc778 | +2,173 |\\n| \uc678\uad6d\uc778 | -1,303 |\\n| \uae30\uad00 | -759 |\\n| \uae30\ud0c0\ubc95\uc778 | -1,105 |\\n\\n\ucf54\uc2a4\ud53c\uc5d0\uc11c\ub294 \uc678\uad6d\uc778\uacfc \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc5d0\uc11c\ub294 \uac1c\uc778\uc774 \uc21c\ub9e4\uc218\ud588\uace0 \uc678\uad6d\uc778\uacfc \uae30\uad00\uc774 \uc21c\ub9e4\ub3c4\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uc758 \ucf54\uc2a4\ud53c \uc21c\ub9e4\ub3c4 \uaddc\ubaa8\uac00 \uc774\ub0a0 \uc218\uae09\uc5d0\uc11c \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uac15\ud588\ub358 \ud14c\ub9c8\uc640 \ud750\ub984\\n\\n\uc9c0\uc218 \ud558\ub77d \uc18d\uc5d0\uc11c\ub3c4 \uc0c1\uc2b9\ud55c \ud14c\ub9c8\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d\ud22c\uc790\uc99d\uad8c MTS \uae30\uc900 \ub9c8\uac10 \ud14c\ub9c8 \uc0c1\uc2b9\ub960\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.<br/>\\n\\n| \ud14c\ub9c8 | \ub4f1\ub77d\ub960 |\\n| --- | --- |\\n| \ub9c8\ub9ac\ud654\ub098(\ub300\ub9c8) \uad00\ub828\uc8fc | +14.58% |\\n| \ub9c8\uc774\ud06c\ub85cLED | +6.08% |\\n| \ud648\ub124\ud2b8\uc6cc\ud06c | +3.31% |\\n| \uc740\ud589 | +1.75% |\\n| \ubcf4\ud5d8 | +1.66% |\\n\\n\uae08\uc735 \ud14c\ub9c8\uc778 \uc740\ud589\uacfc \ubcf4\ud5d8\uc774 \uc9c0\uc218 \ud558\ub77d \uc18d\uc5d0\uc11c\ub3c4 \uc0c1\uc2b9\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc2dc\uc7a5 \ube0c\ub9ac\ud551\uc5d0\uc11c\ub294 \uae09\ub77d\uc7a5 \uc18d HBM \ub300\ud615\uc8fc \uc0c1\uc2b9 \ub9c8\uac10\uacfc \uae08\uc735\xb7\uad11\ud1b5\uc2e0 \uc21c\ud658\ub9e4, \ubc30\ud130\ub9ac \uc57d\uc138\ub97c \uc5b8\uae09\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad00\ub828 \ubcf4\ub3c4\uc5d0\uc11c\ub294 \uc5ed\ub300 \ucd5c\uace0 \uc2e4\uc801\uc5d0\ub3c4 \ub300\ud615 \ubc18\ub3c4\uccb4\uc8fc\uc758 \uc8fc\uac00\uac00 5%\ub300 \ud558\ub77d\ud588\ub2e4\uace0 \uc804\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218 \ud558\ub77d\uc758 \ubc30\uacbd\uc73c\ub85c \ud2b9\uc815 \uc885\ubaa9\uc758 \ud750\ub984\uc744 \ub2e8\uc815\ud558\uae30\ub294 \uc5b4\ub824\uc6b0\uba70, \uc774\ub294 \ucc38\uace0\uc6a9 \ud750\ub984 \uc815\ub9ac\uc785\ub2c8\ub2e4.<br/>\\n\\n## \ub0b4\uc77c \ud655\uc778\ud560 \uc810\\n\\n\ucf54\uc2a4\ud53c\uac00 6,000\uc120\uc744 \ud68c\ubcf5\ud558\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ucf54\uc2a4\ub2e5\uc774 750\uc120 \ubd80\uadfc\uc5d0\uc11c \uc9c0\uc9c0\ub418\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uad00\uc758 \ucf54\uc2a4\ud53c \uc21c\ub9e4\ub3c4 \ud750\ub984\uc774 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uae08\uc735 \ud14c\ub9c8\uc758 \uc0c1\ub300\uc801 \uac15\uc138\uac00 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud560 \ud544\uc694\uac00 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\uc774\ub0a0 \uad6d\ub0b4 \uc99d\uc2dc\ub294 \ub450 \uc9c0\uc218 \ubaa8\ub450 \ud558\ub77d \ub9c8\uac10\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\xb7\ud574\uc124 \ubaa9\uc801\uc758 \uc2dc\uc7a5 \uc815\ub9ac\uc774\uba70, \ub9e4\uc218\xb7\ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>"},{"id":"market-section-opening","metadata":{"permalink":"/blog/market/market-section-opening","source":"@site/market/2026-10-29-market-section-opening/index.mdx","title":"\uc2dc\ud669 \uc139\uc158 \uc2dc\uc791 \uc548\ub0b4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\uc548\ub0b4","permalink":"/blog/market/tags/\uc548\ub0b4"}],"readingTime":1.1,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"market-section-opening","title":"\uc2dc\ud669 \uc139\uc158 \uc2dc\uc791 \uc548\ub0b4","authors":["way"],"tags":["market","\uc2dc\ud669","\uc548\ub0b4"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \uad6d\ub0b4 \uc7a5 \ub9c8\uac10 \uc815\ub9ac","permalink":"/blog/market/2026-10-29-domestic-market-close"},"nextItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","permalink":"/blog/market/2026-10-29-nasdaq-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\ube14\ub85c\uadf8\uc5d0 \uc2dc\ud669 \uc139\uc158\uc744 \uc0c8\ub85c \uc5f4\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uc774 \uc139\uc158\uc5d0\uc11c \ub2e4\ub8e8\ub294 \uae00\\n\\n\uad6d\ub0b4 \uc2dc\uc7a5\uacfc \ub098\uc2a4\ub2e5 \uc2dc\uc7a5\uc744 \uac01\uac01 \uc7a5 \uc624\ud508, \uc7a5\uc911, \uc7a5 \ub9c8\uac10 \uae30\uc900\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uae00\uc740 \ud3c9\uc77c \uc624\uc804 9\uc2dc 30\ubd84, \uc624\ud6c4 12\uc2dc 30\ubd84, \uc624\ud6c4 4\uc2dc\uc5d0 \uc62c\ub77c\uac11\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uae00\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 \uae30\uc900 \uc624\uc804 10\uc2dc, \uc624\ud6c4 1\uc2dc, \uc624\ud6c4 4\uc2dc 20\ubd84\uc5d0 \uc62c\ub77c\uac11\ub2c8\ub2e4.<br/>\\n\ud55c\uad6d \uacf5\ud734\uc77c\uc774\ub098 \ubbf8\uad6d \ud734\uc7a5\uc77c\uc5d0\ub294 \ud574\ub2f9 \uc2dc\uc7a5 \uae00\uc774 \uc62c\ub77c\uac00\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \uae00\uc5d0 \ud3ec\ud568\ub418\ub294 \ub370\uc774\ud130\\n\\n\uac01 \uae00\uc5d0\ub294 \ud574\ub2f9 \uc2dc\uc810\uc758 \ub124\uc774\ubc84 \ucc28\ud2b8 \ub370\uc774\ud130 \uc2a4\ub0c5\uc0f7\uc774 \ud3ec\ud568\ub429\ub2c8\ub2e4.<br/>\\n\uc9c0\uc218\uc640 \uc804\uc77c \ub300\ube44, \ub4f1\ub77d\ub960, \uc2dc\uac00\uc640 \uace0\uac00, \uc800\uac00, \uac70\ub798\ub7c9\uacfc \uac70\ub798\ub300\uae08\uc744 \ud45c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 \uae00\uc5d0\ub294 \ucd5c\uadfc 5\uac70\ub798\uc77c \uc77c\ubd09 \uc885\uac00\ub3c4 \ud568\uaed8 \uc2e3\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uae00\uc5d0\ub294 \ub098\uc2a4\ub2e5 \uc885\ud569\uc744 \uc911\uc2ec\uc73c\ub85c \ub2e4\uc6b0\uc640 S&P500 \ud750\ub984\ub3c4 \ud568\uaed8 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc218\uce58\ub294 \uc870\ud68c \uc2dc\uc810\uc758 \uc2a4\ub0c5\uc0f7\uc774\uba70, \ucd9c\ucc98 \ub9c1\ud06c\ub97c \ud568\uaed8 \ub0a8\uae41\ub2c8\ub2e4.<br/>\\n\\n#### \ud655\uc778\ud560 \uc810\\n\\n\uc774 \uc139\uc158\uc758 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub429\ub2c8\ub2e4.<br/>\\n\ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc73c\uba70, \ubaa9\ud45c\uc8fc\uac00\ub97c \uc81c\uc2dc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc2a4\ub0c5\uc0f7\uc740 \ud655\uc815\uce58\uac00 \uc544\ub2c8\ub77c \ud574\ub2f9 \uc2dc\uc810\uae4c\uc9c0\uc758 \ud750\ub984\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5 \ub9c8\uac10 \uae00\uc758 \uc218\uce58\uc640 \uc7a5\uc911 \uae00\uc758 \uc218\uce58\uac00 \ub2e4\ub97c \uc218 \uc788\ub294 \uc774\uc720\ub3c4 \uc5ec\uae30\uc5d0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\\n#### \ub9c8\uce58\uba70\\n\\n\uc55e\uc73c\ub85c\ub294 \uac1c\uc7a5 \uc9c1\ud6c4\uc758 \ubc29\ud5a5\uacfc \uc7a5\uc911 \ud750\ub984, \ub9c8\uac10 \uacb0\uacfc\ub97c \uac19\uc740 \uae30\uc900\uc73c\ub85c \uc774\uc5b4\uc11c \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124\uc744 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70, \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-10-29-nasdaq-market-midday","metadata":{"permalink":"/blog/market/2026-10-29-nasdaq-market-midday","source":"@site/market/2026-10-29-nasdaq-market-midday/index.mdx","title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc911","permalink":"/blog/market/tags/\uc7a5\uc911"}],"readingTime":3.07,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-29-nasdaq-market-midday","title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc911"]},"unlisted":false,"prevItem":{"title":"\uc2dc\ud669 \uc139\uc158 \uc2dc\uc791 \uc548\ub0b4","permalink":"/blog/market/market-section-opening"},"nextItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","permalink":"/blog/market/2026-10-29-nasdaq-market-open"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5\uc911 \uc694\uc57d\\n\\n\ub098\uc2a4\ub2e5\uc740 \ud558\ub77d \ud750\ub984\uc744 \uc774\uc5b4\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5 \uc624\ud508 \uc774\ud6c4 \uc18c\ud3ed \ubc18\ub4f1\ud588\uc73c\ub098 \uc804\uc77c \ub300\ube44 \ud558\ub77d \uc0c1\ud0dc\ub294 \uc720\uc9c0\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub0a0 \ud558\ub77d\uc758 \uc911\uc2ec\uc5d0\ub294 \ub300\ud615 \uae30\uc220\uae30\uc5c5 \uc2e4\uc801\uc5d0 \ub300\ud55c \uc2e4\ub9dd\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc54c\ud30c\ubcb3\uc758 3\ubd84\uae30 \uc2e4\uc801\uc774 \uc2dc\uc7a5 \uc608\uc0c1\uce58\ub97c \ubc11\ub3cc\uc558\ub2e4\ub294 \ubcf4\ub3c4\uac00 \uc7a5 \ucd08\ubc18\ubd80\ud130 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790\uc5d0 \ub300\ud55c \uc218\uc775\uc131 \uc6b0\ub824\ub3c4 \uae30\uc220\uc8fc \uc804\ubc18\uc758 \uc2ec\ub9ac\ub97c \uc555\ubc15\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 9\uc6d4 \uac1c\uc778\uc18c\ube44\uc9c0\ucd9c \ubb3c\uac00\uc9c0\uc218\ub294 \ucee8\uc13c\uc11c\uc2a4\uc5d0 \ubd80\ud569\ud588\uace0 \uad6d\ub0b4\ucd1d\uc0dd\uc0b0\uc740 \ucee8\uc13c\uc11c\uc2a4\ub97c \uc18c\ud3ed \uc0c1\ud68c\ud588\ub2e4\ub294 \uc18c\uc2dd\uc774 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc2dc\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 |\\n| --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 26,210.96 | -338.89 | -1.28% | 26,549.85 | 26,201.82 | 26,286.46 | 26,053.16 |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 10\uc6d4 29\uc77c 12\uc2dc 57\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 10\uc6d4 30\uc77c 01\uc2dc 57\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc218\uce58\ub294 \uc7a5\uc774 \uc9c4\ud589 \uc911\uc774\ub77c \uacc4\uc18d \ubcc0\ud558\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569 \uc218\uce58\ub294 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc640 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc5d0\uc11c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uad50\ucc28\uac12\ub3c4 \uac19\uc740 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 26,197.14, \uc804\uc77c \ub300\ube44 -352.71, \ub4f1\ub77d\ub960 -1.33%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub294 26,549.85\ub85c \ub124\uc774\ubc84 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 \uc7a5\uc911 \uace0\uac00\ub294 26,273.73, \uc7a5\uc911 \uc800\uac00\ub294 26,076.80\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \ucd9c\ucc98\uc758 \ud604\uc7ac\uac00 \ucc28\uc774\ub294 \uc870\ud68c \uc2dc\uac01 \ucc28\uc774\ub85c \uc124\uba85\ub429\ub2c8\ub2e4.<br/>\\n\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ud750\ub984\\n\\nS&P500\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub099\ud3ed\uc774 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900 S&P500\uc740 7,715.09, \uc804\uc77c \ub300\ube44 -28.89, \ub4f1\ub77d\ub960 -0.37%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,743.98\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \uc7a5\uc911 \uace0\uac00\ub294 7,729.59, \uc7a5\uc911 \uc800\uac00\ub294 7,699.80\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \uc7a5\uc911 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \uae30\uc220\uc8fc \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\uc804\uacfc \uc624\ud6c4 \ud750\ub984 \ubcc0\ud654\\n\\n\uc2dc\uac00 \ub300\ube44 \ubc29\ud5a5 \uc804\ud658\uc740 \ub098\ud0c0\ub098\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5\uc740 \uc2dc\uac00 26,201.82\uc5d0\uc11c \ucd9c\ubc1c\ud574 \uc7a5\uc911 \ud604\uc7ac\uac00 26,210.96\uc73c\ub85c \uc2dc\uac00 \uc704\uc5d0\uc11c \uac70\ub798\ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc804\uc77c \uc885\uac00 \ub300\ube44\ub85c\ub294 \uc5ec\uc804\ud788 1% \ub118\ub294 \ud558\ub77d \uc0c1\ud0dc\uc785\ub2c8\ub2e4.<br/>\\n\uc7a5 \uc624\ud508 \uc2a4\ub0c5\uc0f7(\ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 09\uc2dc 59\ubd84)\uc758 \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 26,170.19\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \ud604\uc7ac\uac00\ub294 \uc624\ud508 \uc2a4\ub0c5\uc0f7\ubcf4\ub2e4 \uc62c\ub790\uc73c\ub098 \ud558\ub77d \ubc29\ud5a5 \uc790\uccb4\ub294 \ubc14\ub00c\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc800\uac00 26,053.16\uc5d0\uc11c \ubc18\ub4f1\ud574 \uace0\uac00 26,286.46\uae4c\uc9c0 \uc62c\ub790\uc73c\ub098 \uc0c1\uc2b9 \uc804\ud658\uc73c\ub85c \ubcf4\uae30\ub294 \uc5b4\ub835\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900\uc73c\ub85c\ub3c4 \uac19\uc740 \ud750\ub984\uc774 \ud655\uc778\ub429\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 \uc7a5 \uc624\ud508 \ub2f9\uc2dc 26,154.79\uc5d0\uc11c \uc7a5\uc911 26,197.14\ub85c \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 \uc7a5\uc911 \uace0\uac00\ub294 26,200.39\uc5d0\uc11c 26,273.73\uc73c\ub85c \ud655\ub300\ub410\uace0 \uc7a5\uc911 \uc800\uac00\ub294 26,076.80\uc744 \uc720\uc9c0\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nS&P500\ub3c4 \uc7a5 \uc624\ud508 \ub2f9\uc2dc 7,709.43\uc5d0\uc11c \uc7a5\uc911 7,715.09\ub85c \uc18c\ud3ed \uc62c\ub790\uc2b5\ub2c8\ub2e4.<br/>\\n\uc624\uc804\uc758 \ud558\ub77d\uc774 \uc624\ud6c4 \ub4e4\uc5b4 \uc644\ub9cc\ud574\uc84c\uc73c\ub098 \ubc29\ud5a5\uc774 \ubc14\ub010 \uac83\uc740 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uac10\uae4c\uc9c0 \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \uc54c\ud30c\ubcb3 \uc2e4\uc801 \uc2e4\ub9dd\uc5d0 \ub530\ub978 \ud558\ub77d \uc555\ub825\uc774 \ub9c8\uac10\uae4c\uc9c0 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uc800\uac00 26,053.16 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \uac1c\uc778\uc18c\ube44\uc9c0\ucd9c \ubb3c\uac00\uc9c0\uc218\uc640 \uad6d\ub0b4\ucd1d\uc0dd\uc0b0 \uc9c0\ud45c\uac00 \uc7a5 \ud6c4\ubc18 \uc2ec\ub9ac\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, S&P500\uacfc \ub098\uc2a4\ub2e5\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \ub9c8\uac10\uae4c\uc9c0 \uc881\ud600\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub2e4\uc12f\uc9f8, \uc7a5 \ub9c8\uac10 \ub54c\uae4c\uc9c0 \uac70\ub798\ub7c9\uacfc \uace0\uac00\uc640 \uc800\uac00\uc758 \ubc94\uc704\uac00 \uc5b4\ub5bb\uac8c \ubcc0\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5\uc911 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ud655\uc815\ub41c \uacb0\uacfc\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc2e4\uc801 \uc2e4\ub9dd\uacfc \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc218\uc775\uc131 \uc6b0\ub824 \uc18d\uc5d0 \ud558\ub77d \ud750\ub984\uc744 \uc774\uc5b4\uac00\uace0 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58\ub85c \ud655\uc778\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>"},{"id":"2026-10-29-nasdaq-market-open","metadata":{"permalink":"/blog/market/2026-10-29-nasdaq-market-open","source":"@site/market/2026-10-29-nasdaq-market-open/index.mdx","title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-29T00:00:00.000Z","tags":[{"inline":true,"label":"market","permalink":"/blog/market/tags/market"},{"inline":true,"label":"\uc2dc\ud669","permalink":"/blog/market/tags/\uc2dc\ud669"},{"inline":true,"label":"\ub098\uc2a4\ub2e5","permalink":"/blog/market/tags/\ub098\uc2a4\ub2e5"},{"inline":true,"label":"\uc7a5\uc624\ud508","permalink":"/blog/market/tags/\uc7a5\uc624\ud508"}],"readingTime":2.53,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/market/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"2026-10-29-nasdaq-market-open","title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \uc815\ub9ac","authors":["way"],"tags":["market","\uc2dc\ud669","\ub098\uc2a4\ub2e5","\uc7a5\uc624\ud508"]},"unlisted":false,"prevItem":{"title":"2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5\uc911 \uc815\ub9ac","permalink":"/blog/market/2026-10-29-nasdaq-market-midday"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 29\uc77c \ub098\uc2a4\ub2e5 \uc7a5 \uc624\ud508 \ud750\ub984\uc744 \uc218\uce58 \uc911\uc2ec\uc73c\ub85c \uc815\ub9ac\ud569\ub2c8\ub2e4.<br/>\\n\\n## \uac1c\uc7a5 \ubc30\uacbd\\n\\n\ub098\uc2a4\ub2e5\uc740 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uac1c\uc7a5 \uc804 \uc7ac\ub8cc\ub85c\ub294 \ub300\ud615 \uae30\uc220\uae30\uc5c5 \uc2e4\uc801\uc5d0 \ub300\ud55c \ud3c9\uac00\uac00 \uac00\uc7a5 \ucef8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc54c\ud30c\ubcb3\uc740 3\ubd84\uae30 \ub9e4\ucd9c\uacfc \uc870\uc815 \uc8fc\ub2f9\uc21c\uc774\uc775\uc774 \uc2dc\uc7a5 \uc608\uc0c1\uce58\ub97c \ubc11\ub3cc\uc558\ub2e4\ub294 \ubcf4\ub3c4\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4.<br/>\\n\uc2dc\uac04\uc678 \uac70\ub798\uc5d0\uc11c \uc54c\ud30c\ubcb3\uc774 \uae09\ub77d\ud588\ub2e4\ub294 \ubcf4\ub3c4\ub3c4 \ud568\uaed8 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790\uc5d0 \ub300\ud55c \uc218\uc775\uc131 \uc6b0\ub824\uac00 \uae30\uc220\uc8fc \uc911\uc2ec\uc758 \ub098\uc2a4\ub2e5 \uc120\ubb3c\uacfc \ucd08\ubc18 \ud750\ub984\uc744 \uc555\ubc15\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ubc18\uba74 9\uc6d4 \uac1c\uc778\uc18c\ube44\uc9c0\ucd9c \ubb3c\uac00\uc9c0\uc218\ub294 \ucee8\uc13c\uc11c\uc2a4\uc5d0 \ubd80\ud569\ud588\uace0 \uad6d\ub0b4\ucd1d\uc0dd\uc0b0\uc740 \ucee8\uc13c\uc11c\uc2a4\ub97c \uc18c\ud3ed \uc0c1\ud68c\ud588\ub2e4\ub294 \uc18c\uc2dd\uc774 \uc804\ud574\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc77c\ub77c\uc774\ub9b4\ub9ac\ub294 \ube44\ub9cc\uacfc \ub2f9\ub1e8\ubcd1 \uce58\ub8cc\uc81c \uc218\uc694 \uc99d\uac00\uc5d0 \ud798\uc785\uc5b4 \ud638\uc2e4\uc801\uc744 \uae30\ub85d\ud588\ub2e4\ub294 \uc18c\uc2dd\ub3c4 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \uad50\uc721\uacfc \ud574\uc124 \ubaa9\uc801\uc73c\ub85c \uc791\uc131\ub418\uc5c8\uc73c\uba70 \ud2b9\uc815 \uc885\ubaa9\uc758 \ub9e4\uc218\ub098 \ub9e4\ub3c4\ub97c \uad8c\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc624\ub298\uc758 \uc2a4\ub0c5\uc0f7\\n\\n| \uc9c0\uc218 | \ud604\uc7ac\uac00 | \uc804\uc77c \ub300\ube44 | \ub4f1\ub77d\ub960 | \uc804\uc77c \uc885\uac00 | \uc2dc\uac00 | \uc7a5\uc911 \uace0\uac00 | \uc7a5\uc911 \uc800\uac00 | \uac70\ub798\ub7c9 |\\n| --- | --- | --- | --- | --- | --- | --- | --- | --- |\\n| \ub098\uc2a4\ub2e5 \uc885\ud569 | 26,170.19 | -379.66 | -1.43% | 26,549.85 | 26,201.82 | 26,209.84 | 26,053.16 | 191,612\ucc9c\uc8fc |\\n\\n\uc2a4\ub0c5\uc0f7 \uae30\uc900 \uc2dc\uac01\uc740 \ubbf8\uad6d \ub3d9\ubd80\uc2dc\uac04 2026\ub144 10\uc6d4 29\uc77c 09\uc2dc 59\ubd84, \ud55c\uad6d\uc2dc\uac04 2026\ub144 10\uc6d4 29\uc77c 22\uc2dc 59\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \uc218\uce58\ub294 \uc7a5\uc774 \uc9c4\ud589 \uc911\uc774\ub77c \uacc4\uc18d \ubcc0\ud558\ub294 \ud615\uc131 \uc911\uc778 \uc218\uce58\uc785\ub2c8\ub2e4.<br/>\\n\ub098\uc2a4\ub2e5 \uc885\ud569 \uc218\uce58\ub294 [\ub124\uc774\ubc84 \uc6d4\ub4dc \ucc28\ud2b8](https://stock.naver.com/worldstock/index/.IXIC/price)\uc640 [\ub124\uc774\ubc84 \uae08\uc735 \uc6d4\ub4dc \uc2dc\uc138](https://finance.naver.com/world/sise.naver?symbol=NAS@IXIC)\uc5d0\uc11c \ud655\uc778\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 28\uc77c \uc885\uac00 26,549.85\ub294 \ub124\uc774\ubc84 \uc77c\ubcc4 \uc2dc\uc138\uc640 \uc704 \uc804\uc77c \uc885\uac00 \uac12\uc774 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uad50\ucc28\uac12\ub3c4 \uac19\uc740 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ub098\uc2a4\ub2e5 \uc885\ud569\uc740 26,154.79, \uc804\uc77c \ub300\ube44 -395.06, \ub4f1\ub77d\ub960 -1.49%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c \uc804\uc77c \uc885\uac00\ub294 26,549.85\ub85c \ub124\uc774\ubc84 \uc804\uc77c \uc885\uac00\uc640 \uc77c\uce58\ud569\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 \uc7a5\uc911 \uace0\uac00\ub294 26,200.39, \uc7a5\uc911 \uc800\uac00\ub294 26,076.80\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub450 \ucd9c\ucc98\uc758 \ud604\uc7ac\uac00 \ucc28\uc774\ub294 \uc870\ud68c \uc2dc\uac01 \ucc28\uc774\ub85c \uc124\uba85\ub429\ub2c8\ub2e4.<br/>\\n\\n\\n## \ucc28\ud2b8\\n\\n\ucd5c\uadfc 20\uac70\ub798\uc77c \uc77c\ubd09 \ucc28\ud2b8\uc785\ub2c8\ub2e4.<br/>\\n\ube68\uac04 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub192\uc740 \ub0a0, \ud30c\ub780 \ubd09\uc740 \uc885\uac00\uac00 \uc2dc\uac00\ubcf4\ub2e4 \ub0ae\uc740 \ub0a0\uc785\ub2c8\ub2e4.<br/>\\n\ub2f9\uc77c \ubd09\uc740 \ud615\uc131 \uc911\uc778 \ubd09\uc73c\ub85c, \ub9c8\uac10 \uc804\uc5d0\ub294 \uacc4\uc18d \ubcc0\ud569\ub2c8\ub2e4.<br/>\\n![\ub098\uc2a4\ub2e5 \uc885\ud569 \uc77c\ubd09 \ucc28\ud2b8](./nasdaq.png)\\n\\n## \ub2e4\uc6b0\uc640 S&P500 \ud750\ub984\\n\\nS&P500\uc740 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \ub099\ud3ed\uc774 \uc791\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uae30\uc900 S&P500\uc740 7,709.43, \uc804\uc77c \ub300\ube44 -34.55, \ub4f1\ub77d\ub960 -0.45%\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \uac12\uc73c\ub85c \uc5ed\uc0b0\ud55c S&P500 \uc804\uc77c \uc885\uac00\ub294 7,743.98\uc785\ub2c8\ub2e4.<br/>\\n\ud55c\ud22c MTS \ucc28\ud2b8 \ubc30\uc5f4 \uae30\uc900 S&P500 \uc7a5\uc911 \uace0\uac00\ub294 7,712.89, \uc7a5\uc911 \uc800\uac00\ub294 7,699.80\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\ub294 \uc774\ubc88 \uc2a4\ub0c5\uc0f7\uc5d0\uc11c \ud55c\ud22c MTS \ud574\uc678 \ub300\uc2dc\ubcf4\ub4dc \uc9c0\uc218 \ubaa9\ub85d\uc5d0 \ud3ec\ud568\ub418\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\uc6b0\uc9c0\uc218\uc758 \uc7a5 \uc624\ud508 \uc218\uce58\ub294 \ud655\uc778 \ud544\uc694\ub85c \ud45c\uae30\ud569\ub2c8\ub2e4.<br/>\\nS&P500\uc758 \ub099\ud3ed\uc774 \ub098\uc2a4\ub2e5\ubcf4\ub2e4 \uc791\uc558\ub2e4\ub294 \uc810\uc5d0\uc11c \ud558\ub77d \uc555\ub825\uc740 \uae30\uc220\uc8fc \ucabd\uc5d0 \ub354 \uc9d1\uc911\ub410\uc2b5\ub2c8\ub2e4.<br/>\\n\\n## \uc7a5 \ucd08\ubc18 \ud655\uc778\ud560 \uc810\\n\\n\uccab\uc9f8, \uc54c\ud30c\ubcb3 \uc2e4\uc801\uc5d0 \ub300\ud55c \uc2dc\uc7a5\uc758 \ud3c9\uac00\uac00 \uc7a5\uc911\uc5d0 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub458\uc9f8, \uac1c\uc778\uc18c\ube44\uc9c0\ucd9c \ubb3c\uac00\uc9c0\uc218\uc640 \uad6d\ub0b4\ucd1d\uc0dd\uc0b0 \uc9c0\ud45c\uac00 \uc7a5\uc911 \uc2ec\ub9ac\uc5d0 \ubbf8\uce58\ub294 \uc601\ud5a5\uc744 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc14b\uc9f8, \ub098\uc2a4\ub2e5\uc774 \uc7a5\uc911 \uc800\uac00 26,053.16 \ubd80\uadfc\uc744 \uc9c0\ud0a4\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub137\uc9f8, S&P500\uacfc \ub098\uc2a4\ub2e5\uc758 \ub099\ud3ed \ucc28\uc774\uac00 \uc7a5\uc911\uc5d0 \uc881\ud600\uc9c0\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\ub2e4\uc12f\uc9f8, \uc7a5 \ub9c8\uac10 \ub54c\uae4c\uc9c0 \uac70\ub798\ub7c9\uacfc \uace0\uac00\uc640 \uc800\uac00\uc758 \ubc94\uc704\uac00 \uc5b4\ub5bb\uac8c \ubcc0\ud558\ub294\uc9c0 \ud655\uc778\ud569\ub2c8\ub2e4.<br/>\\n\uc7a5 \ucd08\ubc18 \uc218\uce58\ub294 \ubc29\ud5a5\uc744 \ubcf4\uc5ec\uc904 \ubfd0\uc774\uba70 \ud655\uc815\ub41c \uacb0\uacfc\uac00 \uc544\ub2d9\ub2c8\ub2e4.<br/>\\n\\n## \ub9c8\uce58\uba70\\n\\n\ub098\uc2a4\ub2e5\uc740 \uc2e4\uc801 \uc2e4\ub9dd\uacfc \uc778\uacf5\uc9c0\ub2a5 \ud22c\uc790 \uc218\uc775\uc131 \uc6b0\ub824 \uc18d\uc5d0 \ud558\ub77d \ucd9c\ubc1c\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774 \uae00\uc740 \ub9e4\uc218\ub098 \ub9e4\ub3c4 \uad8c\uc720\uac00 \uc544\ub2c8\uba70 \uc7a5\uc911 \ud750\ub984\uc744 \uc218\uce58\ub85c \ud655\uc778\ud558\ub294 \ub370 \ubaa9\uc801\uc774 \uc788\uc2b5\ub2c8\ub2e4.<br/>"}]}}')}}]);